def _tour_cost(self, tour):
    # tour: sequence of indices (list or ndarray)
    # Adaptive implementation:
    # - For small tours, use a simple Python loop to avoid numpy overhead.
    # - For larger tours, use a vectorized numpy approach.
    dm = self.distance_matrix

    # Handle empty or None-like inputs
    if tour is None:
        return 0.0
    try:
        n = len(tour)
    except TypeError:
        # Not a sized sequence (e.g., generator) -> fallback to numpy approach
        t = np.asarray(list(tour), dtype=int)
        if t.size == 0:
            return 0.0
        return float(dm[t, np.roll(t, -1)].sum())

    if n == 0:
        return 0.0

    # Small tours: use Python loop (lower overhead for small n)
    if n < 100:
        total = 0.0
        prev = tour[0]
        for cur in tour[1:]:
            total += dm[prev, cur]
            prev = cur
        # add return edge back to start
        total += dm[prev, tour[0]]
        return float(total)

    # Large tours: keep the vectorized numpy version for speed
    t = np.asarray(tour, dtype=int)
    return float(dm[t, np.roll(t, -1)].sum())
